import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import {
	Template,
	TemplateId,
	type TemplateSummary,
} from "@logistack/contracts";

/** Generated by `scripts/convert.ts`; never edited by hand. */
export const catalogDir = join(import.meta.dir, "../catalog");

let index: TemplateSummary[] | undefined;

/** The gallery index, read once. */
export function catalogIndex(): TemplateSummary[] {
	index ??= JSON.parse(
		readFileSync(join(catalogDir, "index.json"), "utf8"),
	) as TemplateSummary[];
	return index;
}

/** One template, parsed; undefined for an id the catalog does not have. */
export function readTemplate(id: string): Template | undefined {
	if (!TemplateId.safeParse(id).success) return undefined;
	const path = join(catalogDir, `${id}.json`);
	if (!existsSync(path)) return undefined;
	return Template.parse(JSON.parse(readFileSync(path, "utf8")));
}

/** Absolute path of a logo named by a template's `logo`, or undefined when it is not one. */
export function logoPath(logo: string): string | undefined {
	if (!/^logos\/[a-z0-9-]+\.(svg|png|jpg|webp)$/.test(logo)) return undefined;
	const path = join(catalogDir, logo);
	return existsSync(path) ? path : undefined;
}
